{
  "findings": [
    {
      "check_id": "CKV_GCP_121 is not applicable, but the concept applies",
      "title": "Cloud SQL instance does not have deletion protection enabled",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "MEDIUM",
      "explanation": "The Cloud SQL instance is not protected against accidental deletion, which could result in data loss."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Cloud SQL instance is exposed to the internet",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "CRITICAL",
      "explanation": "The Cloud SQL instance is authorized to accept connections from any IP address (0.0.0.0/0), making it publicly exposed."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Cloud SQL instance does not require SSL/TLS connections",
      "resource": "google_sql_database_instance.operational_database",
      "severity": "HIGH",
      "explanation": "The Cloud SQL instance allows non-SSL/TLS connections, potentially exposing data in transit to interception."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"operational_database\" {\n  name             = \"autonomous-drone-delivery-management-platform-sql-operational\"\n  database_version = \"POSTGRES_14\"\n  region           = var.region\n  settings {\n    tier = var.database_tier\n    ip_configuration {\n      ipv4_enabled = true\n      authorized_networks {\n        value = \"10.0.0.0/16\"\n        name  = \"internal-network\"\n      }\n      require_ssl = true\n    }\n    backup_configuration {\n      enabled                        = true\n      start_time                     = \"03:00\"\n      point_in_time_recovery_enabled = true\n    }\n    database_flags {\n      name  = \"log_statement\"\n      value = \"all\"\n    }\n  }\n  deletion_protection = true\n}",
  "fix_summary": "Enabled deletion protection for the Cloud SQL instance, restricted authorized networks to internal IP range only, and enforced SSL/TLS connections."
}
